def solve(inputs):
    a, m = inputs['A'], int(inputs['MOD'])
    m0, x0, x1 = m, 0, 1
    if m == 1: return 0
    while a > 1:
        q = int(a / m)
        m, a = a % m, m
        x0, x1 = x1 - q * x0, x0
    if x1 < 0: x1 += inputs['MOD']
    return int(x1)
